// MARK: - Loader (generated once, not a symbol)

/// Decodes each SVG once and caches the `NSImage`. Main-actor because `NSImage` is not Sendable.
@MainActor enum NRSymbolStore {
    private static var symbols: [NRSymbol: NSImage] = [:]
    private static var logos: [NRLogo: NSImage] = [:]

    static func image(for s: NRSymbol) -> NSImage {
        if let i = symbols[s] { return i }
        let i = decode(s.svg, name: s.rawValue)
        i.isTemplate = true
        symbols[s] = i
        return i
    }

    static func image(for l: NRLogo) -> NSImage {
        if let i = logos[l] { return i }
        let i = decode(l.svg, name: "\(l)")
        i.isTemplate = false
        logos[l] = i
        return i
    }

    private static func decode(_ svg: String, name: String) -> NSImage {
        guard let image = NSImage(data: Data(svg.utf8)) else {
            preconditionFailure("NRSymbol: \(name) failed to decode — the SVG in /design is not what the generator saw")
        }
        image.setName(name)
        return image
    }
}
